import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association to outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue
        x = feats.x[:, i]
        y = feats.y
        mean1 = np.mean(x[y==1])
        mean0 = np.mean(x[y==0])
        effect = abs(mean1 - mean0)
        tstat, _ = stats.ttest_ind(x[y==1], x[y==0], equal_var=False)
        effects.append((effect, abs(tstat), fid))

    effects.sort(reverse=True)

    # Select top candidates
    candidates = [fid for _, _, fid in effects[:20]]

    # Remove near-duplicates based on correlation
    keep = set()
    corr_matrix = np.corrcoef(feats.x[:, [feats.column(fid) for fid in candidates]])
    for i in range(len(candidates)):
        fid1 = candidates[i]
        if fid1 in keep:
            continue
        keep.add(fid1)
        for j in range(i+1, len(candidates)):
            fid2 = candidates[j]
            if abs(corr_matrix[i,j]) >= 0.6:
                keep.discard(fid2)

    candidates = list(keep)

    # Look for interaction terms
    best_product = None
    best_p = 1.0
    best_effect = 0

    # Test products of top candidates
    for i, fid1 in enumerate(candidates):
        for j, fid2 in enumerate(candidates):
            if i >= j:
                continue
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            product = feats.x[:, col1] * feats.x[:, col2]

            # Simple test for association with outcome
            corr = np.corrcoef(product, feats.y)[0,1]
            if abs(corr) > best_effect:
                best_effect = abs(corr)
                best_product = (fid1, fid2)

    # Return result
    if best_product and best_effect > 0.05:
        return Design(
            drivers=(best_product[0], best_product[1]),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={}
        )
    elif len(candidates) > 0:
        return Design(
            drivers=(candidates[0],),
            columns=(candidates[0],),
            products=(),
            loadings={candidates[0]: 1.0}
        )
    else:
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )

